export interface ConnectorConfig {
  /** Airtable Base ID (e.g., 'appXXXXXXXXXXXXXX') */
  baseId: string;
  /** Airtable Table Name or ID */
  tableName: string;
  /** Airtable Personal Access Token. In production, set via AIRTABLE_API_KEY env var. */
  apiKey: string;
  /** Optional record ID. If omitted, the connector will look up the record by email using filterByFormula. */
  recordId?: string;
  /** Injected fetch for testing. Uses global fetch in production. */
  fetch?: typeof fetch;
}

export interface JotformSubmission {
  email: string;
  first_name?: string;
  last_name?: string;
  phone?: string;
  address?: string;
}

export interface UpdateResult {
  recordId: string;
  updatedFields: Record<string, string>;
}

const FIELD_MAP: ReadonlyArray<{ source: keyof JotformSubmission; target: string }> = [
  { source: 'first_name', target: 'First Name' },
  { source: 'last_name', target: 'Last Name' },
  { source: 'phone', target: 'Phone' },
  { source: 'address', target: 'Address' },
] as const;

function buildAirtableUrl(baseId: string, tableName: string, recordId?: string): string {
  const base = `https://api.airtable.com/v0/${encodeURIComponent(baseId)}/${encodeURIComponent(tableName)}`;
  return recordId ? `${base}/${encodeURIComponent(recordId)}` : base;
}

async function findRecordByEmail(
  fetch: typeof fetch,
  baseId: string,
  tableName: string,
  apiKey: string,
  email: string,
): Promise<string> {
  const formula = `{Email} = '${email.replace(/'/g, "\\'")}'`;
  const url = `${buildAirtableUrl(baseId, tableName)}?filterByFormula=${encodeURIComponent(formula)}`;
  const response = await fetch(url, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
  });
  if (!response.ok) {
    throw new Error(`Airtable lookup failed: ${response.status} ${response.statusText} at GET ${url}`);
  }
  const data = (await response.json()) as { records?: Array<{ id: string }> };
  const record = data.records?.[0];
  if (!record) {
    throw new Error(`No Airtable record found for email: ${email}`);
  }
  return record.id;
}

function buildPatchBody(submission: JotformSubmission): Record<string, string> {
  const fields: Record<string, string> = {};
  for (const { source, target } of FIELD_MAP) {
    const value = submission[source];
    if (value !== undefined && value !== '') {
      fields[target] = value;
    }
  }
  return fields;
}

export async function handle(payload: JotformSubmission, config: ConnectorConfig): Promise<UpdateResult> {
  const fetchImpl = config.fetch ?? fetch;
  const { baseId, tableName, apiKey, recordId: providedRecordId } = config;

  if (!payload.email || payload.email.trim() === '') {
    throw new Error('Missing required field: email');
  }

  const recordId = providedRecordId ?? (await findRecordByEmail(fetchImpl, baseId, tableName, apiKey, payload.email));

  const fields = buildPatchBody(payload);
  if (Object.keys(fields).length === 0) {
    return { recordId, updatedFields: {} };
  }

  const patchUrl = buildAirtableUrl(baseId, tableName, recordId);
  const patchResponse = await fetchImpl(patchUrl, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ fields }),
  });

  if (!patchResponse.ok) {
    throw new Error(`Airtable update failed: ${patchResponse.status} ${patchResponse.statusText} at PATCH ${patchUrl}`);
  }

  const patchData = (await patchResponse.json()) as { id: string; fields: Record<string, string> };
  return { recordId: patchData.id, updatedFields: patchData.fields };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, JotformSubmission, UpdateResult } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      apiKey: 'test-api-key',
      recordId: 'rec123',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmission, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.recordId).toBe('rec123');
    expect(result.updatedFields['First Name']).toBe('John');
  });
});

describe('handle', () => {
  it('looks up record by email when recordId not provided and patches non-empty fields', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('filterByFormula')) {
        return jsonResponse({ records: [{ id: 'rec456', fields: {} }] });
      }
      if (req.method === 'PATCH' && req.url.endsWith('/rec456')) {
        expect(req.json).toEqual({
          fields: {
            'First Name': 'Jane',
            'Last Name': 'Smith',
            'Phone': '555-5678',
            'Address': '456 Oak Ave',
          },
        });
        return jsonResponse({ id: 'rec456', fields: req.json.fields, createdTime: '2026-01-25T07:39:00.000Z' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      apiKey: 'test-api-key',
      fetch,
    };

    const payload: JotformSubmission = {
      email: 'jane@example.com',
      first_name: 'Jane',
      last_name: 'Smith',
      phone: '555-5678',
      address: '456 Oak Ave',
    };

    const result = await handle(payload, config);
    expect(result.recordId).toBe('rec456');
    expect(calls.length).toBe(2);
    expect(calls[0].method).toBe('GET');
    expect(calls[1].method).toBe('PATCH');
  });

  it('only includes non-empty fields in PATCH body', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('filterByFormula')) {
        return jsonResponse({ records: [{ id: 'rec789', fields: {} }] });
      }
      if (req.method === 'PATCH' && req.url.endsWith('/rec789')) {
        expect(req.json).toEqual({
          fields: {
            'First Name': 'Bob',
            'Address': '789 Pine Rd',
          },
        });
        return jsonResponse({ id: 'rec789', fields: req.json.fields, createdTime: '2026-01-25T07:39:00.000Z' });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      apiKey: 'test-api-key',
      fetch,
    };

    const payload: JotformSubmission = {
      email: 'bob@example.com',
      first_name: 'Bob',
      last_name: '',
      phone: undefined,
      address: '789 Pine Rd',
    };

    const result = await handle(payload, config);
    expect(result.updatedFields).toEqual({ 'First Name': 'Bob', 'Address': '789 Pine Rd' });
  });

  it('throws when email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      apiKey: 'test-api-key',
      fetch,
    };
    const payload = { first_name: 'Test' } as unknown as JotformSubmission;
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email');
  });

  it('throws when email is empty string', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      apiKey: 'test-api-key',
      fetch,
    };
    const payload: JotformSubmission = { email: '', first_name: 'Test' };
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: email');
  });

  it('throws on non-2xx response from Airtable lookup', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      apiKey: 'bad-key',
      fetch,
    };
    const payload: JotformSubmission = { email: 'test@example.com' };
    await expect(handle(payload, config)).rejects.toThrow('Airtable lookup failed: 401 Unauthorized at GET');
  });

  it('throws on non-2xx response from Airtable PATCH', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') {
        return jsonResponse({ records: [{ id: 'rec999', fields: {} }] });
      }
      return jsonResponse({ error: 'Rate limited' }, 429);
    });

    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      apiKey: 'test-api-key',
      fetch,
    };
    const payload: JotformSubmission = { email: 'test@example.com', first_name: 'Test' };
    await expect(handle(payload, config)).rejects.toThrow('Airtable update failed: 429 Too Many Requests at PATCH');
    expect(calls.length).toBe(2);
  });

  it('throws when no record found for email', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ records: [] }));
    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      apiKey: 'test-api-key',
      fetch,
    };
    const payload: JotformSubmission = { email: 'nonexistent@example.com' };
    await expect(handle(payload, config)).rejects.toThrow('No Airtable record found for email: nonexistent@example.com');
  });

  it('uses provided recordId and skips lookup', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'PATCH' && req.url.endsWith('/recProvided')) {
        expect(req.json).toEqual({ fields: { 'First Name': 'Provided' } });
        return jsonResponse({ id: 'recProvided', fields: req.json.fields, createdTime: '2026-01-25T07:39:00.000Z' });
      }
      return jsonResponse({ error: 'should not be called' }, 404);
    });

    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      apiKey: 'test-api-key',
      recordId: 'recProvided',
      fetch,
    };
    const payload: JotformSubmission = { email: 'ignored@example.com', first_name: 'Provided' };
    const result = await handle(payload, config);
    expect(result.recordId).toBe('recProvided');
    expect(calls.length).toBe(1);
    expect(calls[0].method).toBe('PATCH');
  });

  it('returns empty updatedFields when all mapped fields are empty', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') {
        return jsonResponse({ records: [{ id: 'recEmpty', fields: {} }] });
      }
      return jsonResponse({ error: 'should not PATCH' }, 404);
    });

    const config: ConnectorConfig = {
      baseId: 'appTestBase',
      tableName: 'TestTable',
      apiKey: 'test-api-key',
      fetch,
    };
    const payload: JotformSubmission = { email: 'empty@example.com', first_name: '', last_name: '', phone: '', address: '' };
    const result = await handle(payload, config);
    expect(result.recordId).toBe('recEmpty');
    expect(result.updatedFields).toEqual({});
    expect(calls.length).toBe(1); // only GET, no PATCH
  });
});

